const PREFERENCES_JS="(()=>{\n const originals=new WeakMap();\n const pairs={\n '中俄双语 / 中文 + Русский':['中俄双语','Китайский + русский'],\n '中文 / Китайский':['中文','Китайский'], 'Русский / 俄语':['俄语','Русский'],\n '实验 / 实习分组 · Подгруппа':['实验 / 实习分组','Подгруппа'],\n '语言课程 · Язык':['语言课程','Язык занятий'],\n '班级 / Группа':['班级','Группа'],\n '我的双语课表 · Моё расписание':['我的课表','Моё расписание'],\n '工艺机械与设备 / Технологические машины и оборудование':['工艺机械与设备','Технологические машины и оборудование'],\n '同一时段可能有不同分组，请选自己的分组；公共课保留。 / Выберите свою подгруппу; общие занятия показываются всегда.':['同一时段可能有不同分组，请选自己的分组；公共课保留。','Выберите свою подгруппу; общие занятия показываются всегда.'],\n 'iPhone 使用与同步说明 / Помощь':['iPhone 使用与同步说明','Помощь для iPhone'],\n '苹果日历 / Календарь Apple':['苹果日历','Календарь Apple'],\n '中俄双语 / 中文 + Русский · 自动同步 / Синхронизация':['中俄双语 · 自动同步','Китайский + русский · Синхронизация'],\n '我的双语课表':['我的双语课表','Моё расписание']\n };\n function label(text){if(text.includes('\\n'))return text.split('\\n').map(label).join('\\n');const value=text.trim();if(uiLanguage==='both')return text;if(pairs[value])return text.replace(value,pairs[value][uiLanguage==='zh'?0:1]);const parts=value.split(' / ');if(parts.length===2&&/[\\u3400-\\u9fff]/.test(parts[0])&&/[А-Яа-яЁё]/.test(parts[1]))return text.replace(value,uiLanguage==='zh'?parts[0]:(/\\d+/.test(parts[0])&&!/\\d/.test(parts[1])?parts[0].match(/\\d+/)[0]+' ':'')+parts[1]);return text;}\n applyLanguage=()=>{\n  document.documentElement.lang=uiLanguage==='ru'?'ru':'zh-CN';document.body.dataset.uiLanguage=uiLanguage;\n  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('script,style,textarea,option[data-i18n-zh]'))continue;if(!originals.has(node))originals.set(node,node.nodeValue);const original=originals.get(node);const help=node.parentElement.closest('#help p');node.nodeValue=help&&((uiLanguage==='ru'&&/[\\u3400-\\u9fff]/.test(original)&&!/[А-Яа-яЁё]/.test(original))||(uiLanguage==='zh'&&/[А-Яа-яЁё]/.test(original)&&!/[\\u3400-\\u9fff]/.test(original)))?'':label(original);}\n  document.querySelectorAll('[data-i18n-zh]').forEach(el=>{el.textContent=uiLanguage==='both'?el.dataset.i18nZh+' / '+el.dataset.i18nRu:uiLanguage==='ru'?el.dataset.i18nRu:el.dataset.i18nZh;});\n  if(uiLanguage==='ru'){$('weeklabel').textContent=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(week+'T12:00:00Z'));$('daylabel').textContent=(selected===todayMSK()?'Сегодня · ':'')+new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',weekday:'short',timeZone:'UTC'}).format(new Date(selected+'T12:00:00Z'));$('weekcount').textContent='На неделе: '+filtered().filter(e=>e.date>=week&&e.date<=add(week,6)).length+' занятий · Подгруппы учитываются отдельно';}\n  if(uiLanguage==='zh'){$('daylabel').textContent=(selected===todayMSK()?'今天 · ':'')+selected.slice(5).replace('-','月')+'日';}\n  document.querySelectorAll('#days .day span').forEach((el,i)=>{el.textContent=tr(weekday[(i+1)%7],ruDays[(i+1)%7]);});\n };\n\n const selectedMinutes=()=>{const n=Number(store.get('narfu-reminder-minutes')??15);return [5,10,15,30,60].includes(n)?n:15;};\n const subscription=async()=>{const reg=await navigator.serviceWorker.ready;return await reg.pushManager.getSubscription();};\n const pushRequest=async(path,extra={})=>{const sub=await subscription();if(!sub)throw new Error(tr('请先开启系统通知','Сначала включите уведомления'));const res=await fetch('/api/push/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:sub.toJSON(),...extra})});const result=await res.json();if(!res.ok)throw new Error(result.error||'HTTP '+res.status);return result;};\n function updatePushState(message){const el=$('push-state');if(el)el.textContent=message||tr(store.get('narfu-push-enabled')==='true'?'此设备已开启系统提醒':'此设备尚未开启系统提醒',store.get('narfu-push-enabled')==='true'?'Уведомления включены на устройстве':'Уведомления ещё не включены');}\n window.syncPushPreferences=async()=>{if(store.get('narfu-push-enabled')!=='true')return;await pushRequest('subscribe',{minutes:selectedMinutes(),subgroup:$('subgroup').value,language:$('language').value,uiLanguage});};\n async function enablePush(){try{\n  if(/iPad|iPhone|iPod/.test(navigator.userAgent)&&!navigator.standalone&&!matchMedia('(display-mode: standalone)').matches)throw new Error(tr('请先在 Safari 共享菜单中添加到主屏幕，再从主屏幕打开。','Добавьте сайт на экран «Домой» через Safari и откройте оттуда.'));\n  if(!('Notification'in window)||!('PushManager'in window))throw new Error(tr('当前浏览器不支持系统推送','Этот браузер не поддерживает push'));\n  const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error(tr('通知未获允许，请在手机系统设置中检查','Проверьте разрешение уведомлений в настройках телефона'));\n  const config=await(await fetch('/api/push/config',{cache:'no-store'})).json();if(!config.enabled)throw new Error(tr('提醒后台正在配置，请稍后重试','Сервис уведомлений ещё настраивается'));\n  const reg=await navigator.serviceWorker.ready;await reg.update();let sub=await reg.pushManager.getSubscription();\n  if(!sub){const encoded=config.publicKey.replace(/-/g,'+').replace(/_/g,'/');const key=Uint8Array.from(atob(encoded+'='.repeat((4-encoded.length%4)%4)),c=>c.charCodeAt(0));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}\n  store.set('narfu-push-enabled','true');await window.syncPushPreferences();updatePushState();\n }catch(error){store.set('narfu-push-enabled','false');updatePushState(error.message);}}\n window.openPreferences=async()=>{try{if(!$('preferences')){const r=await fetch('/settings.html?v=6',{cache:'force-cache'});if(!r.ok)throw new Error();$('settings-slot').innerHTML=await r.text();$('ui-language').onchange=()=>{uiLanguage=$('ui-language').value;store.set('narfu-ui-language',uiLanguage);render();window.syncPushPreferences().catch(e=>updatePushState(e.message));};$('reminder-minutes').onchange=()=>{store.set('narfu-reminder-minutes',$('reminder-minutes').value);window.syncPushPreferences().then(()=>updatePushState()).catch(e=>updatePushState(e.message));};$('enable-push').onclick=enablePush;$('test-push').onclick=async()=>{try{await pushRequest('test');updatePushState(tr('测试通知已交给推送服务，请查看系统通知。','Проверочное уведомление отправлено в push-сервис.'));}catch(e){updatePushState(e.message);}};$('disable-push').onclick=async()=>{try{await pushRequest('unsubscribe');const sub=await subscription();if(sub)await sub.unsubscribe();store.set('narfu-push-enabled','false');updatePushState();}catch(e){updatePushState(e.message);}};}\n $('ui-language').value=uiLanguage;$('reminder-minutes').value=String(selectedMinutes());updatePushState();applyLanguage();$('preferences').showModal();\n }catch{toast(tr('设置暂时无法加载，请重试','Не удалось загрузить настройки. Повторите позже.'));}};\n applyLanguage();render();if(store.get('narfu-push-enabled')==='true')window.syncPushPreferences().catch(()=>{});\n})();\n";
const TEACHER_FULL_NAMES={"Багрецова Н.В.":{"ru":"Багрецова Нина Викторовна","zh":"巴格列佐娃·妮娜·维克托罗芙娜"},"Бадогина А.И.":{"ru":"Бадогина Алена Игоревна","zh":"巴多吉娜·阿廖娜·伊戈列芙娜"},"Бейм В.В.":{"ru":"Бейм Виктория Валерьевна","zh":"贝姆·维多利亚·瓦列里耶芙娜"},"Долгова И.И.":{"ru":"Долгова Ирина Ивановна","zh":"多尔戈娃·伊琳娜·伊万诺芙娜"},"Елепов А.А.":{"ru":"Елепов Александр Алексеевич","zh":"叶列波夫·亚历山大·阿列克谢耶维奇"},"Епимахова А.С.":{"ru":"Епимахова Александра Сергеевна","zh":"叶皮马霍娃·亚历山德拉·谢尔盖耶芙娜"},"Коваленко О.Л.":{"ru":"Коваленко Олег Леонидович","zh":"科瓦连科·奥列格·列昂尼多维奇"},"Лоренц А.С.":{"ru":"Лоренц Анатолий Сергеевич","zh":"洛伦茨·阿纳托利·谢尔盖耶维奇"},"Марьянчик В.А.":{"ru":"Марьянчик Виктория Анатольевна","zh":"马里扬奇克·维多利亚·阿纳托利耶芙娜"},"Попова Л.В.":{"ru":"Попова Лариса Владиславовна","zh":"波波娃·拉里萨·弗拉季斯拉沃芙娜"},"Степырева Е.В.":{"ru":"Степырева Елена Валерьевна","zh":"斯捷皮列娃·叶莲娜·瓦列里耶芙娜"},"Третьяков С.И.":{"ru":"Третьяков Сергей Иванович","zh":"特列季亚科夫·谢尔盖·伊万诺维奇"},"Шостенко Д.Н.":{"ru":"Шостенко Денис Николаевич","zh":"绍斯坚科·杰尼斯·尼古拉耶维奇"},"Вихарев А.Н.":{"ru":"Вихарев Александр Николаевич","zh":"维哈列夫·亚历山大·尼古拉耶维奇"},"Теселкин М.В.":{"ru":"Теселкин Михаил Владиславович","zh":"捷谢尔金·米哈伊尔·弗拉季斯拉沃维奇"}};
function fullTeacher(name=''){return TEACHER_FULL_NAMES[name.trim()]||Object.values(TEACHER_FULL_NAMES).find(v=>v.ru===name.trim())||null;}
const PAGE_GZIP = "";
const teacherSurnames = {'Шостенко':'绍斯坚科','Коваленко':'科瓦连科','Епимахова':'叶皮马霍娃','Попова':'波波娃','Елепов':'叶列波夫','Степырева':'斯捷皮列娃','Бейм':'贝姆','Марьянчик':'马里扬奇克','Лоренц':'洛伦茨','Бадогина':'巴多吉娜','Багрецова':'巴格列佐娃'};
export function teacherChinese(name='') {return fullTeacher(name)?.zh||null;}
export function locationChinese(location='') {
 if(!location)return null;
 if(!/Северной Двины|Ломоносова/.test(location))return null;
 return location.replace(/г\.\s*Архангельск/g,'阿尔汉格尔斯克市').replace(/наб\.\s*Северной Двины/g,'北德维纳河滨街').replace(/пр\.\s*Ломоносова/g,'罗蒙诺索夫大街').replace(/\bауд\.\s*/gu,'教室 ').replace(/ауд\.\s*/g,'教室 ').replace(/д\.\s*(\d+)/g,'$1号').replace(/(?:корп\.|к\.)\s*(\d+)/g,'$1号楼').replace(/罗蒙诺索夫大街,\s*(\d+)/g,'罗蒙诺索夫大街$1号').replace(/(街)\s*,\s*/g,'$1').replace(/\s*,\s*/g,'，').trim();
}
export function subgroupChinese(group=''){return group?group.replace(/Подгруппа\s*/g,'分组 ').replace(/Поток\s*/g,'合班 ').replace(/Немецкий язык/g,'德语').replace(/практика/g,'实习').replace(/_англ/g,'_英语').replace(/_нем/g,'_德语').replace(/_рус/g,'_俄语'):'';}
